    private static func names(_ v:UInt32,_ m:[(UInt32,String)])->String{m.compactMap{v&$0.0 != 0 ? $0.1:nil}.joined(separator:" ")}
    private static func link(_ f:OniDatFile,_ c:inout Int)->String{guard let i=linkIndex(f,&c)else{return ""};return i<f.instances.count ? f.instances[i].fullName:""}
    private static func linkIndex(_ f:OniDatFile,_ c:inout Int)->Int?{let v=ru32(f.data,c);c+=4;return v==0 ? nil:Int(v>>8)}
    private static func rs(_ d:Data,_ o:Int,_ n:Int)->String{let e=min(o+n,d.count),z=d[o..<e].firstIndex(of:0) ?? e;return String(data:d[o..<z],encoding:.utf8) ?? ""}
    private static func rf(_ d:Data,_ c:inout Int)->String{let v=Float(bitPattern:ru32(d,c));c+=4;return v==0 ? "0":String(v)}
    private static func ru16(_ d:Data,_ c:inout Int)->UInt16{let v=UInt16(d[c])|UInt16(d[c+1])<<8;c+=2;return v}
    private static func ri16(_ d:Data,_ c:inout Int)->Int16{Int16(bitPattern:ru16(d,&c))}
    private static func ru32(_ d:Data,_ o:Int)->UInt32{UInt32(d[o])|UInt32(d[o+1])<<8|UInt32(d[o+2])<<16|UInt32(d[o+3])<<24}
    private static func ri32(_ d:Data,_ c:inout Int)->Int32{let v=Int32(bitPattern:ru32(d,c));c+=4;return v}
}
